506:pub fn summarize_events(text: &str) -> EventSummary {
507:    let mut s = EventSummary::default();
508:    for line in text.split('\n') {
509:        let t = line.trim();
510:        if t.is_empty() || !t.starts_with('{') {
511:            continue;
512:        }
513:        let Ok(obj) = serde_json::from_str::<Value>(t) else {
514:            continue;
515:        };
516:        let ty = obj.get("type").and_then(|v| v.as_str()).unwrap_or("");
517:        if ty == "assistant" {
518:            s.assistant_count += 1;
519:            let content = obj
520:                .get("message")
521:                .and_then(|m| m.get("content"))
522:                .and_then(|c| c.as_array())
523:                .cloned()
524:                .unwrap_or_default();
525:            for b in content.iter().filter(|b| b.is_object()) {
526:                match b.get("type").and_then(|v| v.as_str()).unwrap_or("") {
527:                    "text" => {
528:                        let tx = b.get("text").and_then(|v| v.as_str()).unwrap_or("");
529:                        if !tx.trim().is_empty() {
530:                            s.last_assistant_text = tx.to_string();
531:                        }
532:                    }
533:                    "tool_use" => {
534:                        let name = b
535:                            .get("name")
536:                            .and_then(|v| v.as_str())
537:                            .unwrap_or("(unnamed)")
538:                            .to_string();
539:                        *s.tool_calls.entry(name).or_insert(0) += 1;
540:                    }
541:                    _ => {}
542:                }
543:            }
544:        } else if ty == "result" {
545:            s.has_result = true;
546:            s.result_text = obj
547:                .get("result")
548:                .and_then(|v| v.as_str())
549:                .unwrap_or("")
550:                .to_string();
551:            s.is_error = obj.get("is_error").and_then(|v| v.as_bool()) == Some(true);
552:            s.num_turns = obj.get("num_turns").and_then(|v| {
553:                v.as_i64()
554:                    .or_else(|| v.as_str().and_then(|x| x.parse().ok()))
555:            });
556:            // (0.2.4, F89-5) Rebuild usage from an ALLOW LIST of numeric counters â€” never clone the
557:            // whole usage object (a sentinel/secret in an extra field must not reach run.json).
558:            s.usage = claude_usage(&obj);
559:        }
560:    }
561:    s
562:}
