1386:fn do_resume_foreground(o: &Options, rec_dir: &Path, rec: &RunRecord) -> i32 {
1387:    if rec.status != "quota" && rec.status != "timeout" {
1388:        return refuse(&format!(
1389:            "work run {} is in state {}, not quota or timeout; nothing to resume.",
1390:            rec.id, rec.status
1391:        ));
1392:    }
1393:    if rec.quota.as_ref().map(|q| q.exhausted).unwrap_or(false) {
1394:        return refuse(&format!(
1395:            "work run {} has spent its resume cap ({}); it needs a human.",
1396:            rec.id,
1397:            eff_max_resumes_rec(o, rec)
1398:        ));
1399:    }
1400:    let renv = match resume_env(o, rec, rec_dir) {
1401:        Ok(e) => e,
1402:        Err(why) => return refuse(&why),
1403:    };
1404:    match resume_once(&renv, rec_dir) {
1405:        Ok(status) => {
1406:            if status == "quota" {
1407:                let nrec = read_record(rec_dir).ok().flatten().unwrap_or_default();
1408:                foreground_quota(o, rec_dir, &nrec)
1409:            } else {
1410:                exit_for(&status)
1411:            }
1412:        }
1413:        Err(why) => refuse(&why),
1414:    }
1415:}
